const listPageSettingsByPages = `-- name: ListPageSettingsByPages :many
SELECT page, ` + "`" + `key` + "`" + `, value, description, updated_at
FROM page_settings
WHERE page IN (/*SLICE:pages*/?)
`

// Public GET /page-settings?page=home&page=courses — batch fetch.
func (q *Queries) ListPageSettingsByPages(ctx context.Context, pages []string) ([]PageSetting, error) {
	query := listPageSettingsByPages
	var queryParams []interface{}
	if len(pages) > 0 {
		for _, v := range pages {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:pages*/?", strings.Repeat(",?", len(pages))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:pages*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PageSetting{}
	for rows.Next() {
		var i PageSetting
		if err := rows.Scan(
			&i.Page,
			&i.Key,
			&i.Value,
			&i.Description,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

