const listSiteSettingsByKeys = `-- name: ListSiteSettingsByKeys :many
SELECT ` + "`" + `key` + "`" + `, value, scope, description, updated_at
FROM site_settings
WHERE ` + "`" + `key` + "`" + ` IN (/*SLICE:keys*/?)
`

// Public GET /site-settings?keys=a,b,c — batch fetch by key set.
func (q *Queries) ListSiteSettingsByKeys(ctx context.Context, keys []string) ([]SiteSetting, error) {
	query := listSiteSettingsByKeys
	var queryParams []interface{}
	if len(keys) > 0 {
		for _, v := range keys {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:keys*/?", strings.Repeat(",?", len(keys))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:keys*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SiteSetting{}
	for rows.Next() {
		var i SiteSetting
		if err := rows.Scan(
			&i.Key,
			&i.Value,
			&i.Scope,
			&i.Description,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

